    29  fr_pair_t *fr_raw_from_network(TALLOC_CTX *ctx, fr_dict_attr_t const *parent, uint8_t const *data, size_t data_len)
    30  {
    31          fr_pair_t *vp;
    32          fr_dict_attr_t *unknown;
    33          fr_dict_attr_t const *child;
    34
    35  #if defined(__clang_analyzer__) || !defined(NDEBUG)
    36          if (!parent->parent) return NULL; /* stupid static analyzers */
    37  #endif
    38
    39          /*
    40           *      Build an unknown attr of the entire data.
    41           */
    42          unknown = fr_dict_unknown_attr_afrom_da(ctx, parent);
    43          if (!unknown) return NULL;
    44          unknown->flags.is_raw = 1;
    45
    46          vp = fr_pair_afrom_da(ctx, unknown); /* makes a copy of 'child' */
    47          child = unknown;
    48          fr_dict_unknown_free(&child);
    49          if (!vp) return NULL;
    50
    51          if (fr_value_box_from_network(vp, &vp->data, vp->da->type, vp->da, data, data_len, true) < 0) {
    52                  talloc_free(vp);
    53                  return NULL;
    54          }
    55
    56          vp->type = VT_DATA;
    57          return vp;
    58  }
